hall = {}
def hang_shield(name, version, deeds): hall[name] = (version, set(deeds))
def seekers(deeds):
    return [n for n, (v, d) in hall.items() if deeds in d]
hang_shield("indexer", "2.1", ["index"]); hang_shield("scribe", "1.0", ["write"])
print("seekers of indexing:", seekers("index"))
assert seekers("index") == ["indexer"]

clans = {}
def settle(lineage, tool):
    hall = clans
    for part in lineage.split("."): hall = hall.setdefault(part, {})
    hall["shield"] = tool
settle("archive.index.v2", "indexer"); settle("archive.parse.v1", "parser")
print("archive clan:", list(clans["archive"]))
assert set(clans["archive"]) == {"index", "parse"}

provisions = {"indexer": "2.1.0", "python": "3.11.2"}
print("sealed provisions:", provisions)
assert provisions["indexer"] == "2.1.0"

