shields = {"indexer": {"stations": ["outer", "inner"]}, "vault": {"stations": ["inner"]}}
def unveil(stations):
    return [n for n, s in shields.items() if set(s["stations"]) & set(stations)]
print("outer sees:", unveil(["outer"]))
assert unveil(["outer"]) == ["indexer"]

filing = {}
def file_shield(name, tale):
    for w in tale.lower().split(): filing.setdefault(w, set()).add(name)
